-- Durable pre/post analysis data. Runtime also creates these through SQLAlchemy.
CREATE TABLE IF NOT EXISTS prepost_analysis_days (id SERIAL PRIMARY KEY, trade_date DATE UNIQUE NOT NULL, is_trading_day BOOLEAN NOT NULL DEFAULT TRUE, status VARCHAR(32) NOT NULL, current_phase VARCHAR(32) NOT NULL, market_bias VARCHAR(40) NOT NULL, market_score DOUBLE PRECISION, risk_level VARCHAR(20) NOT NULL, opening_pattern VARCHAR(80) NOT NULL, strong_industries_json TEXT NOT NULL, weak_industries_json TEXT NOT NULL, day_trade_advice TEXT NOT NULL, stock_advice TEXT NOT NULL, recommended_position VARCHAR(40) NOT NULL, support_json TEXT NOT NULL, resistance_json TEXT NOT NULL, data_as_of TIMESTAMPTZ, prediction_result VARCHAR(20), prediction_details_json TEXT NOT NULL, market_snapshot_json TEXT NOT NULL DEFAULT '{}', score_breakdown_json TEXT NOT NULL DEFAULT '{}', pre_market_prediction_json TEXT NOT NULL DEFAULT '{}', analysis_error TEXT, archived_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS prepost_analysis_messages (id SERIAL PRIMARY KEY, message_id VARCHAR(48) UNIQUE NOT NULL, trade_date DATE NOT NULL, period VARCHAR(20) NOT NULL, category VARCHAR(40) NOT NULL, importance VARCHAR(16) NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, market_impact TEXT NOT NULL, industry_impact_json TEXT NOT NULL, stock_impact_json TEXT NOT NULL, operation_advice TEXT NOT NULL, confidence_score DOUBLE PRECISION NOT NULL, sources_json TEXT NOT NULL, data_time TIMESTAMPTZ NOT NULL, dedupe_key VARCHAR(180) UNIQUE NOT NULL, version INTEGER NOT NULL DEFAULT 1, is_update BOOLEAN NOT NULL DEFAULT FALSE, parent_message_id VARCHAR(48) REFERENCES prepost_analysis_messages(message_id), notification_sent BOOLEAN NOT NULL DEFAULT FALSE, notification_sent_at TIMESTAMPTZ, mail_sent BOOLEAN NOT NULL DEFAULT FALSE, is_marked_important BOOLEAN NOT NULL DEFAULT FALSE, is_followed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS prepost_notification_settings (user_id VARCHAR(80) PRIMARY KEY, pre_market BOOLEAN NOT NULL DEFAULT TRUE, post_market BOOLEAN NOT NULL DEFAULT TRUE, important_events BOOLEAN NOT NULL DEFAULT TRUE, emergency_events BOOLEAN NOT NULL DEFAULT TRUE, mail_enabled BOOLEAN NOT NULL DEFAULT FALSE, minimum_importance VARCHAR(16) NOT NULL DEFAULT 'IMPORTANT', updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS prepost_pending_events (id SERIAL PRIMARY KEY, event_key VARCHAR(160) UNIQUE NOT NULL, target_trade_date DATE NOT NULL, payload_json TEXT NOT NULL, data_time TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
